package br.com.eventmenu.go.printing
import android.Manifest;import android.annotation.SuppressLint;import android.bluetooth.BluetoothManager;import android.content.Context;import android.content.pm.PackageManager;import android.os.Build;import androidx.core.content.ContextCompat;import java.nio.charset.Charset;import java.util.UUID
class BluetoothEscPosPrinter(private val context:Context,private val preferences:PrinterPreferences){private val sppUuid=UUID.fromString("00001101-0000-1000-8000-00805F9B34FB")
 fun hasConnectPermission()=Build.VERSION.SDK_INT<Build.VERSION_CODES.S||ContextCompat.checkSelfPermission(context,Manifest.permission.BLUETOOTH_CONNECT)==PackageManager.PERMISSION_GRANTED
 @SuppressLint("MissingPermission") fun bondedDevices():List<PrinterDevice>{if(!hasConnectPermission())return emptyList();val a=(context.getSystemService(Context.BLUETOOTH_SERVICE)as BluetoothManager).adapter?:return emptyList();return a.bondedDevices.orEmpty().map{PrinterDevice(it.name.orEmpty().ifBlank{"Bluetooth ${it.address.takeLast(5)}"},it.address)}.sortedBy{it.name.lowercase()}}
 @SuppressLint("MissingPermission") fun print(text:String){if(!hasConnectPermission())throw IllegalStateException("Permita acesso aos dispositivos Bluetooth para imprimir.");val settings=preferences.load();if(!settings.enabled||settings.deviceAddress.isBlank())throw IllegalStateException("Configure uma impressora Bluetooth no Perfil.");val a=(context.getSystemService(Context.BLUETOOTH_SERVICE)as BluetoothManager).adapter?:throw IllegalStateException("Bluetooth não disponível neste aparelho.");if(!a.isEnabled)throw IllegalStateException("Ative o Bluetooth antes de imprimir.");val socket=a.getRemoteDevice(settings.deviceAddress).createRfcommSocketToServiceRecord(sppUuid);try{socket.connect();val out=socket.outputStream;out.write(byteArrayOf(0x1B,0x40));val normal=StringBuilder();fun flush(){if(normal.isNotEmpty()){out.write(byteArrayOf(0x1B,0x61,0x00));out.write(wrapReceipt(normal.toString(),settings.columns).toByteArray(Charset.forName("CP860")));normal.clear()}};text.lines().forEach{line->val marker=line.trim();if(marker.startsWith("[[EVENTMENU_QR:")&&marker.endsWith("]]")){flush();val payload=marker.removePrefix("[[EVENTMENU_QR:").removeSuffix("]]" ).trim();if(payload.isNotBlank())writeQr(out,payload)}else normal.appendLine(line)};flush();out.write("\n\n\n".toByteArray(Charsets.US_ASCII));out.write(byteArrayOf(0x1D,0x56,0x01));out.flush()}finally{runCatching{socket.close()}}}
 private fun writeQr(out:java.io.OutputStream,data:String){val bytes=data.toByteArray(Charsets.UTF_8);out.write(byteArrayOf(0x1B,0x61,0x01));out.write(byteArrayOf(0x1D,0x28,0x6B,0x04,0x00,0x31,0x41,0x32,0x00));out.write(byteArrayOf(0x1D,0x28,0x6B,0x03,0x00,0x31,0x43,0x06));out.write(byteArrayOf(0x1D,0x28,0x6B,0x03,0x00,0x31,0x45,0x31));val len=bytes.size+3;out.write(byteArrayOf(0x1D,0x28,0x6B,(len and 0xFF).toByte(),((len shr 8)and 0xFF).toByte(),0x31,0x50,0x30));out.write(bytes);out.write(byteArrayOf(0x1D,0x28,0x6B,0x03,0x00,0x31,0x51,0x30));out.write("\n".toByteArray())}
 private fun wrapReceipt(text:String,columns:Int)=buildString{text.lines().forEach{raw->val line=raw.trimEnd();if(line.length<=columns){appendLine(line);return@forEach};var remaining=line;while(remaining.length>columns){var cut=remaining.lastIndexOf(' ',columns);if(cut<columns/2)cut=columns;appendLine(remaining.substring(0,cut).trimEnd());remaining=remaining.substring(cut).trimStart()};appendLine(remaining)}}}
